<script>
    /* ===========================================
       SLIDE PRESENTATION CONTROLLER
       Handles navigation, animations, progress bar, nav dots
       =========================================== */
    class SlidePresentation {
        constructor() {
            this.slides = document.querySelectorAll('.slide');
            this.currentSlide = 0;
            this.isScrolling = false;

            this.setupIntersectionObserver();
            this.setupKeyboardNav();
            this.setupTouchNav();
            this.setupWheelNav();
            this.setupProgressBar();
            this.setupNavDots();

            // Trigger first slide immediately
            if (this.slides[0]) this.slides[0].classList.add('visible');
        }

        /* Intersection Observer — adds .visible when slides enter viewport */
        setupIntersectionObserver() {
            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('visible');
                        // Update current slide index
                        const idx = Array.from(this.slides).indexOf(entry.target);
                        if (idx !== -1) {
                            this.currentSlide = idx;
                            this.updateNavDots();
                            this.updateProgressBar();
                        }
                    }
                });
            }, { threshold: 0.5 });

            this.slides.forEach(slide => observer.observe(slide));
        }

        /* Keyboard navigation — arrows + space + page keys */
        setupKeyboardNav() {
            document.addEventListener('keydown', (e) => {
                switch(e.key) {
                    case 'ArrowDown':
                    case 'ArrowRight':
                    case ' ':
                        e.preventDefault();
                        this.navigate(1);
                        break;
                    case 'ArrowUp':
                    case 'ArrowLeft':
                        e.preventDefault();
                        this.navigate(-1);
                        break;
                    case 'PageDown':
                        e.preventDefault();
                        this.navigate(1);
                        break;
                    case 'PageUp':
                        e.preventDefault();
                        this.navigate(-1);
                        break;
                    case 'Home':
                        e.preventDefault();
                        this.goToSlide(0);
                        break;
                    case 'End':
                        e.preventDefault();
                        this.goToSlide(this.slides.length - 1);
                        break;
                }
            });
        }

        /* Touch/swipe support */
        setupTouchNav() {
            let touchStartY = 0;
            let touchStartX = 0;

            document.addEventListener('touchstart', (e) => {
                touchStartY = e.touches[0].clientY;
                touchStartX = e.touches[0].clientX;
            }, { passive: true });

            document.addEventListener('touchend', (e) => {
                const dy = touchStartY - e.changedTouches[0].clientY;
                const dx = touchStartX - e.changedTouches[0].clientX;
                if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 50) {
                    this.navigate(dy > 0 ? 1 : -1);
                }
            }, { passive: true });
        }

        /* Mouse wheel navigation — throttled */
        setupWheelNav() {
            document.addEventListener('wheel', (e) => {
                e.preventDefault();
                if (this.isScrolling) return;
                this.isScrolling = true;
                this.navigate(e.deltaY > 0 ? 1 : -1);
                setTimeout(() => { this.isScrolling = false; }, 800);
            }, { passive: false });
        }

        /* Navigate by delta */
        navigate(delta) {
            const newIndex = Math.max(0, Math.min(this.slides.length - 1, this.currentSlide + delta));
            this.goToSlide(newIndex);
        }

        /* Scroll to specific slide */
        goToSlide(idx) {
            if (idx < 0 || idx >= this.slides.length) return;
            this.slides[idx].scrollIntoView({ behavior: 'smooth' });
            this.currentSlide = idx;
            this.updateNavDots();
            this.updateProgressBar();
